import{_ as o,o as t,c as i,a5 as r}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Sequence Flow — View Client Profile","description":"","frontmatter":{},"headers":[],"relativePath":"feature/profile/3-3-3-view-client-profile/sequence-flow.md","filePath":"feature/profile/3-3-3-view-client-profile/sequence-flow.md"}'),n={name:"feature/profile/3-3-3-view-client-profile/sequence-flow.md"};function a(l,e,s,d,c,p){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="sequence-flow-—-view-client-profile" tabindex="-1">Sequence Flow — View Client Profile <a class="header-anchor" href="#sequence-flow-—-view-client-profile" aria-label="Permalink to &quot;Sequence Flow — View Client Profile&quot;">​</a></h1><p>&gt; Supplements <code>spec.md</code> (FR 3.3.3). This file lists each step as actor → action → system, in enough detail to draw the sequence diagram directly — it does not restate business rules (see spec.md for those). &gt; &gt; Updated: 2026-10-02. ClientProfile reworked — owned by the User, independent of any Agency.</p><h2 id="actors" tabindex="-1">Actors <a class="header-anchor" href="#actors" aria-label="Permalink to &quot;Actors&quot;">​</a></h2><ul><li><strong>User</strong> — any signed-in user, owner of zero or more Client Profiles.</li><li><strong>Agency member</strong> — an Owner or Manager viewing a workspace&#39;s Client list.</li><li><strong>Client</strong> — the &quot;My Brand Profiles&quot; screen (<code>/client-profiles</code>) and the Workspace Client list (<code>/workspaces/:id/clients</code>).</li><li><strong>System</strong> — the application services.</li><li><strong>Database</strong> — PostgreSQL (<code>client_profiles</code>, <code>workspace_members</code>).</li></ul><hr><h2 id="key-point-—-a-client-profile-is-owned-by-the-user-never-scoped-to-an-agency" tabindex="-1">Key point — a Client Profile is owned by the User, never scoped to an Agency <a class="header-anchor" href="#key-point-—-a-client-profile-is-owned-by-the-user-never-scoped-to-an-agency" aria-label="Permalink to &quot;Key point — a Client Profile is owned by the User, never scoped to an Agency&quot;">​</a></h2><ul><li>A user may own any number of independent Client Profiles — one per brand/customer they represent (e.g. separate &quot;Nike&quot; and &quot;Adidas&quot; profiles), unrelated to how many Agencies they work with.</li><li>The same profile can be linked (<code>workspace_members.client_profile_id</code>) to any number of workspaces across any number of Agencies simultaneously. There is no &quot;per-Agency copy&quot; — one record, many links.</li></ul><h2 id="flow-a-—-view-my-brand-profiles" tabindex="-1">Flow A — View &quot;My Brand Profiles&quot; <a class="header-anchor" href="#flow-a-—-view-my-brand-profiles" aria-label="Permalink to &quot;Flow A — View &quot;My Brand Profiles&quot;&quot;">​</a></h2><ol><li>User → Client: opens <code>/client-profiles</code>.</li><li>Client → System: requests the signed-in user&#39;s Client Profiles.</li><li>System: a. Resolves the caller&#39;s identity from the access token. b. System → Database: <code>findByUserId(userId)</code> — returns every matching row (possibly empty).</li><li>System → Client: returns the list — <code>id</code>, <code>userId</code>, <code>displayName</code>, <code>company</code>, <code>phone</code>, <code>note</code>, <code>logoUrl</code>, <code>website</code>, <code>industry</code>, <code>location</code>, <code>description</code>, <code>socialLinks</code>, plus brand fields, <code>createdAt</code>, <code>updatedAt</code>.</li><li>Client: renders one card per profile.</li></ol><h2 id="flow-b-—-agency-member-views-a-workspace-s-client-list" tabindex="-1">Flow B — Agency member views a workspace&#39;s Client list <a class="header-anchor" href="#flow-b-—-agency-member-views-a-workspace-s-client-list" aria-label="Permalink to &quot;Flow B — Agency member views a workspace&#39;s Client list&quot;">​</a></h2><ol><li>Agency member → Client: opens <code>/workspaces/:id/clients</code>.</li><li>Client → System: requests <code>GET /api/v1/workspaces/{id}/members</code>.</li><li>System: a. Confirms the Workspace exists and the caller is an active member. b. System → Database: reads every active <code>workspace_members</code> row for that workspace; for role CLIENT rows, resolves the linked Client Profile&#39;s <code>displayName</code>.</li><li>System → Client: returns the member list.</li><li>Client: filters to <code>role === &quot;CLIENT&quot;</code> and displays them, with an &quot;Add client&quot; action for Owner/Manager.</li></ol><hr><h2 id="error-paths" tabindex="-1">Error paths <a class="header-anchor" href="#error-paths" aria-label="Permalink to &quot;Error paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure condition</th><th>HTTP</th><th>ErrorCode</th></tr></thead><tbody><tr><td>View My Brand Profiles (Flow A)</td><td>Missing, expired, or invalid token</td><td>401</td><td><code>UNAUTHORIZED</code></td></tr><tr><td>View Workspace Client list (Flow B)</td><td>Workspace does not exist</td><td>404</td><td><code>WORKSPACE_NOT_FOUND</code></td></tr><tr><td>View Workspace Client list (Flow B)</td><td>Caller not an active member of that workspace</td><td>403</td><td><code>WORKSPACE_ACCESS_DENIED</code></td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Creating a Client Profile happens explicitly on <code>/client-profiles</code> (FR 3.3.4) or inline during a CLIENT invitation accept flow (see <code>agency-workspace/3-4-7-invite-agency-member/sequence-flow.md</code>) — never implicitly, and never keyed by an Agency.</li><li>The old &quot;(user, agency) pair&quot; model (2026-09-21, reverted 2026-10-02) is documented in <code>plan.md</code> §6 for historical context only — do not reintroduce it.</li></ul>',16)])])}const m=o(n,[["render",a]]);export{u as __pageData,m as default};
